/** @param {CalculationInput} record */
export default function calculate(record) {
  const pressure = record.pressureProbe
  const values = Array.isArray(pressure.data) ? pressure.data : [pressure.data]
  const frequencies = pressure.axes[4].ticks
  return {
    dtype: 'float64',
    data: frequencies.map((_, index) => Number(values[index * 2]) / Math.sqrt(2)),
    axes: [{ name: 'frequency', ticks: frequencies, unit: 'Hz' }],
  }
}

/** @param {CalculationInput} record */
export default function calculate(record) {
  const pressure = record.pressureProbe
  const values = Array.isArray(pressure.data) ? pressure.data : [pressure.data]
  const frequencies = pressure.axes[4].ticks
  const amplitudes = frequencies.map((_, index) => Number(values[index * 2]))
  if (amplitudes.some((amplitude) => amplitude <= 0)) throw new Error('SPL requires positive pressure amplitude at the observation point.')
  return {
    dtype: 'float64',
    data: amplitudes.map((amplitude) => 20 * Math.log10(amplitude / (Math.sqrt(2) * 20e-6))),
    axes: [{ name: 'frequency', ticks: frequencies, unit: 'Hz' }],
  }
}
